(function(){
'use strict';
const data=window.CAMPUS_CONTENT, core=window.StudyCore, desktop=window.campusDesktop;
let realEnvironmentView=null,missionView=null,competencyView=null,professionalView=null,recoveryView=null,profileGeneration=0;
const curriculum=data.curriculum, modules=curriculum.modules, lessons=modules.flatMap(m=>m.lessons),main=document.getElementById('main');
let state=core.createState(curriculum),profile=null,labData={},profiles=[],view='home',currentId=null,step='theory',search='',deck=[],deckFilter='all',cardIndex=0,revealed=false,info={},updateStatus={},saveError=null,changeNumber=0,savedNumber=0,saving=null,activeLab=null,labResult=null,labOutput='',systemInfo=null,profileBusy=false,closePending=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const lessonById=id=>lessons.find(l=>l.id===id),moduleOf=id=>modules.find(m=>m.lessons.some(l=>l.id===id)),prog=id=>core.getLesson(state,id);
const btn=(text,attrs='',primary=false)=>`<button class="btn${primary?' primary':''}" ${attrs}>${text}</button>`;
const material=(file,text,cls='btn small')=>`<span class="material-actions"><button class="${cls}" data-material="${esc(file)}">${esc(text)} <span aria-hidden="true">↗</span></button><button class="btn small" data-export-material="${esc(file)}" aria-label="Guardar una copia de ${esc(text)}">Guardar archivo ↓</button></span>`;
const title=(eyebrow,heading,subtitle)=>`<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 tabindex="-1">${esc(heading)}</h1><p>${esc(subtitle)}</p></div><span class="date-tag">CAMPUS DE ESCRITORIO</span></div>`;
const icon=(name)=>{const paths={home:'M3 10 12 3l9 7v11H3Z M9 21v-8h6v8',route:'M4 4h7v16H4Z M13 4h7v16h-7',labs:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M8 15h8',roadmap:'M5 4h14v5H5Z M5 15h14v5H5Z M12 9v6',summary:'M5 3h14v18H5Z M8 8h8 M8 12h8 M8 16h5',final:'M5 3h14v18H5Z M8 10l3 3 5-6',library:'M4 5h5v16H4Z M11 5h4v16h-4 M17 5l4 15',profiles:'M8 8a4 4 0 1 0 8 0 4 4 0 0 0-8 0 M4 22v-3a8 8 0 0 1 16 0v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v4 M12 18v4 M2 12h4 M18 12h4 M5 5l3 3 M16 16l3 3 M19 5l-3 3 M8 16l-3 3'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.route}"/></svg>`};
function announce(s){document.getElementById('announcer').textContent=s;}
let toastTimer;function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');announce(message);clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),6000);}
function warning(){return '';}
function effectivePreferences(){return state.preferences||core.createState(curriculum).preferences;}
function applyPreferences(){const p=effectivePreferences(),r=document.documentElement;const theme=p.theme==='system'?(window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'):p.theme;r.dataset.theme=theme;r.dataset.font=p.font;r.dataset.contrast=p.contrast;r.dataset.spacing=p.spacing;r.dataset.motion=p.motion;r.dataset.focus=String(p.focusMode);document.getElementById('exit-focus').hidden=!p.focusMode;}
function rejectedEvidence(){return professionalView?.rejectedEvidence()||[];}
function updateChrome(){const rejected=rejectedEvidence();const s=core.summary(state,curriculum);document.getElementById('active-profile').textContent=profile?profile.name+' · Perfil local':'Perfiles locales';document.getElementById('app-version').textContent='Versión '+(info.version||'—')+' · Escritorio';document.getElementById('save-status').textContent=closePending?'Finalizando operaciones…':profileBusy?'Cambiando perfil…':rejected.length?'Evidencia sin guardar':saveError?'Cambios sin guardar':saving?'Guardando…':profile?'✓ Guardado en este equipo':'Sin perfil activo';document.getElementById('sidebar-progress').innerHTML=`<span>${s.completed} de ${s.total} clases</span><div class="track" role="progressbar" aria-label="Clases completadas" aria-valuemin="0" aria-valuemax="${s.total}" aria-valuenow="${s.completed}"><span style="width:${s.percent}%"></span></div>`;document.querySelectorAll('.nav-item').forEach(b=>{const selected=b.dataset.view===(view==='lesson'?'route':view==='lab'?'labs':['diagnostic','exam','calendar','spaced-review','learning-history'].includes(view)?'learning':view);b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const err=document.getElementById('save-error');err.hidden=!saveError&&!rejected.length;if(saveError)err.innerHTML=`<strong>No pudimos guardar tu trabajo.</strong> ${esc(saveError.message)} Tus textos siguen en esta sesión. <div class="btn-row">${btn('Reintentar guardado','data-action="retry-save"')}${btn('Recuperar versión guardada…','data-action="reload-profile"')}</div>`;else if(rejected.length)err.innerHTML=`<strong>Hay evidencia sin guardar.</strong> El texto que supera los límites sigue en esta sesión. Volvé para corregirlo o copiarlo; para continuar sin él, descartalo explícitamente. <div class="btn-row">${rejected.map(item=>btn('Volver a '+item.label,`data-view="${item.view}"`)).join('')}${btn('Descartar textos rechazados…','data-action="confirm-discard-evidence"')}</div>`;}
function persist(){changeNumber++;flush().catch(()=>{});updateChrome();}
function lockProfileControls(){document.querySelectorAll('button,input,select,textarea').forEach(el=>{if((profileBusy||closePending)&&!el.disabled){el.disabled=true;el.dataset.profileLock='true';}else if(!profileBusy&&!closePending&&el.dataset.profileLock){el.disabled=false;delete el.dataset.profileLock;}});document.body.setAttribute('aria-busy',String(profileBusy||closePending));}
async function profileOperation(operation,{discard=false}={}){if(profileBusy||closePending)throw new Error('Esperá a que termine la operación pendiente.');if(!discard)guardRejectedEvidence();else professionalView?.discardRejectedEvidence();profileBusy=true;lockProfileControls();updateChrome();try{if(!discard)await flush();return await operation();}finally{profileBusy=false;lockProfileControls();updateChrome();}}
async function flush(){if(saveError)throw saveError;if(saving)return saving;if(!profile||savedNumber===changeNumber)return;const id=profile.id;saving=(async()=>{while(savedNumber<changeNumber){const number=changeNumber;const result=await desktop.saveProfile({id,expectedRevision:profile.revision,study:clone(state),labs:clone(labData)});profile={...profile,revision:result.revision,updatedAt:result.updatedAt};savedNumber=number;}})();updateChrome();try{await saving;}catch(error){saveError=error;throw error;}finally{saving=null;updateChrome();}}
function edit(next){if(!profile||profileBusy)return;state=next;persist();}
function adopt(record){guardRejectedEvidence();disposeHubs();profileGeneration++;profile=record;state=record.study;labData=record.labs||{};changeNumber=0;savedNumber=0;saveError=null;activeLab=null;labResult=null;labOutput='';applyPreferences();}
function commitControl(next){edit(next);return true;}
function changePreferences(patch){edit(core.updatePreferences(state,patch));applyPreferences();return true;}
function focusElement(id){const el=(id&&document.getElementById(id))||main.querySelector('h1')||main;if(!el.hasAttribute('tabindex')&&!/BUTTON|INPUT|SELECT|TEXTAREA/.test(el.tagName))el.tabIndex=-1;el.focus();}
function navigate(target){if(profileBusy)return;view=target;render(true);document.documentElement.scrollTop=0;if(target==='profiles')desktop.listProfiles().then(p=>{profiles=p;if(view==='profiles')render();}).catch(error=>toast(error.message));}
function openLesson(id,notesFirst=false){if(profileBusy||!lessonById(id))return;currentId=id;view='lesson';const p=prog(id);step=notesFirst?'notes':!p.read?'theory':!p.practiceDone||p.answer.trim().length<20?'practice':p.bestScore===null||p.bestScore<2?'quiz':'notes';render(true);}
function modal(titleText,body,action,label){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(titleText)}</h2><p>${esc(body)}</p><div class="btn-row">${btn(label,`data-action="${action}"`,true)}${btn('Cancelar','data-action="cancel-modal"')}</div></section></div>`;root.querySelector('button').focus();}
function closeModal(){document.getElementById('modal-root').replaceChildren();const previous=modalReturnFocus;modalReturnFocus=null;if(previous?.isConnected&&!['BODY','HTML'].includes(previous.tagName))previous.focus();else focusElement();}
function guardRejectedEvidence(){if(!rejectedEvidence().length)return;modal('Hay evidencia sin guardar','Volvé al informe para corregir o copiar el texto que supera los límites. Podés descartar únicamente los textos rechazados y repetir la operación.','discard-evidence','Descartar textos rechazados');throw Error('Hay evidencia sin guardar. Corregila o descartala explícitamente antes de cambiar el perfil.');}
async function beforeClose({discard=false}={}){if(closePending)return;if(!discard&&rejectedEvidence().length){modal('Hay evidencia sin guardar','El texto rechazado sigue en esta sesión, incluso en otras vistas. Cancelá para corregirlo o copiarlo; cerrar sin guardar lo descarta.','discard-close','Cerrar sin guardar');return;}closePending=true;lockProfileControls();updateChrome();try{if(discard)professionalView?.discardRejectedEvidence();else await flush();await desktop.readyToClose();}catch(error){closePending=false;lockProfileControls();updateChrome();modal('No se pudo finalizar el cierre',String(error.message)+' Volvé al campus para revisar tu trabajo, o reintentá el cierre descartando los cambios pendientes.','discard-close','Reintentar cierre sin guardar');}}

function moduleCard(m,index){const count=m.lessons.filter(l=>core.isComplete(prog(l.id))).length;return `<article class="module-card"><div class="card-top"><span class="module-icon" aria-hidden="true">${esc(m.icon||'▤')}</span><span class="pill${count===m.lessons.length?' green':''}">${count===m.lessons.length?'Completado':'MÓDULO '+String(index+1).padStart(2,'0')}</span></div><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="card-meta"><span>${m.lessons.length} clases · ${m.lessons.reduce((n,l)=>n+l.minutes,0)} min orientativos</span><span>${count}/${m.lessons.length}</span></div><div class="track" role="progressbar" aria-label="Avance en ${esc(m.title)}" aria-valuemin="0" aria-valuemax="${m.lessons.length}" aria-valuenow="${count}"><span style="width:${count/m.lessons.length*100}%"></span></div><button class="btn link card-open" data-lesson="${esc((m.lessons.find(l=>!core.isComplete(prog(l.id)))||m.lessons[0]).id)}">${count?'Seguir módulo':'Empezar módulo'} <span aria-hidden="true">→</span></button></article>`;}
function lessonRows(m){return m.lessons.map(l=>{const p=prog(l.id), complete=core.isComplete(p), attempted=p.read||p.answer||p.attempts;return `<button class="lesson-row" data-lesson="${esc(l.id)}"><span class="lesson-number">${String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span><strong>${esc(l.title)}</strong><small>${esc(l.practice.environment)}</small></span><span class="row-end">${complete?'✓ Completada':attempted?'En curso':l.minutes+' min'}<br>${p.attempts?'Mejor: '+p.bestScore+'/3':'→'}</span></button>`;}).join('');}
function route(){const q=search.trim().toLocaleLowerCase('es');let found=0;const html=modules.map((m,i)=>{const selected={...m,lessons:m.lessons.filter(l=>!q||(m.title+' '+l.title+' '+l.objective+' '+l.practice.environment).toLocaleLowerCase('es').includes(q))};found+=selected.lessons.length;return selected.lessons.length?`<section class="module-section"><div class="eyebrow">MÓDULO ${i+1}</div><h2>${esc(m.title)}</h2><p class="muted small">${esc(m.description)}</p><div class="lesson-list">${lessonRows(selected)}</div></section>`:'';}).join('');return title('RUTA ANUAL','Todo en un recorrido.','Seguí el orden sugerido o elegí el tema que necesites. Cada clase integra lectura, práctica, preguntas y resumen.')+`<label class="field" for="lesson-search">Buscar un tema</label><input type="search" class="search" id="lesson-search" value="${esc(search)}" aria-controls="route-results" aria-describedby="route-status" placeholder="Por ejemplo: Windows, memoria, SQL…"><p id="route-status" class="field-hint" role="status" aria-live="polite">${found} clases encontradas.</p><div id="route-results">${html||'<div class="empty">No encontramos ese tema. Probá con otra palabra o borrá la búsqueda.</div>'}</div>`;}
function completion(p){return `<div class="completion-grid"><div class="${p.read?'done':''}">${p.read?'✓':'○'} Lectura</div><div class="${p.practiceDone&&p.answer.trim().length>=20?'done':''}">${p.practiceDone?'✓':'○'} Práctica registrada</div><div class="${p.bestScore>=2?'done':''}">${p.bestScore>=2?'✓':'○'} Preguntas ${p.bestScore===null?'—':p.bestScore+'/3'}</div><div class="${p.notes.trim()?'done':''}">${p.notes.trim()?'✓':'○'} Mi resumen</div></div>`;}
function lesson(){const l=lessonById(currentId),m=moduleOf(currentId),p=prog(l.id);return `<button class="back" data-view="route">← Volver a la ruta anual</button><div class="lesson-heading"><span class="pill green">CLASE ${lessons.indexOf(l)+1} DE ${lessons.length}</span> <span class="small muted">${esc(m.title)} · ${l.minutes} min orientativos</span><h1 id="lesson-title">${esc(l.title)}</h1><p>${esc(l.objective)}</p></div>${warning()}<nav class="stepper" aria-label="Pasos de la clase">${[['theory','Teoría'],['practice','Práctica'],['quiz','Comprobar'],['notes','Mi resumen']].map(([id,label],i)=>`<button id="step-${id}" class="step${step===id?' active':''}" data-step="${id}" ${step===id?'aria-current="step"':''}><span>${i+1}</span>${label}</button>`).join('')}</nav><section class="lesson-panel">${step==='theory'?theory(l,p):step==='practice'?practice(l,p):step==='quiz'?quiz(l,p):notes(l,p)}</section>`;}
function theory(l,p){return `<div class="reader"><p class="scope">LECTURA DE ESTA CLASE · Elaboración docente propia sobre los temas revisados. La revisión de materiales del campus es parcial; el inventario de la biblioteca conserva el detalle.</p>${l.theoryHtml}<div class="bottom-action">${btn(p.read?'✓ Lectura registrada':'Ya leí y comprendí la teoría',`id="mark-read" aria-pressed="${p.read}"`,true)}${btn('Ir a la práctica →','data-step="practice"')}</div></div>`;}
function practice(l,p){const a=l.practice;return `<div class="reader"><div class="eyebrow">DEL CONCEPTO A LA EVIDENCIA</div><h2>${esc(a.title)}</h2><span class="pill">${esc(a.environment)}</span><div class="btn-row" style="margin:18px 0">${(l.practiceLinks||[]).map(r=>material(r.file,r.title)).join('')}</div><ol>${a.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="notice"><strong>Qué tenés que producir</strong>${esc(a.deliverable)}</div><h3>Revisá tu trabajo</h3><ul class="checklist">${a.checks.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><label class="field" for="practice-answer">Tu respuesta y evidencia</label><p id="practice-hint" class="field-hint">Anotá procedimiento, resultado, qué pudiste verificar y qué quedó pendiente. Los archivos y capturas se conservan en tu carpeta de práctica; acá registrás una síntesis. La evidencia de esta práctica se registra manualmente; los simuladores interactivos están en Laboratorios.</p><textarea id="practice-answer" aria-describedby="practice-hint practice-error" data-edit="answer" rows="7" maxlength="20000" placeholder="Qué hice, qué observé, qué concluyo y qué límites tiene…">${esc(p.answer)}</textarea><p id="practice-error" class="error-text" role="alert"></p><div class="bottom-action">${btn(p.practiceDone?'✓ Práctica realizada · desmarcar':'Marcar práctica realizada',`id="practice-done" aria-pressed="${p.practiceDone}"`,true)}${btn('Comprobar lo aprendido →','data-step="quiz"')}</div><p class="field-hint" style="margin-top:15px">Marcala cuando realmente la hayas hecho. Es una declaración tuya; la respuesta abierta queda pendiente de corrección con un tutor.</p></div>`;}
function quizFeedback(l,p){return l.quiz.map(q=>{const chosen=p.lastAnswers[q.id],ok=chosen===q.correct;return `<div class="quiz-feedback${ok?'':' wrong'}" data-feedback><b>${ok?'✓ Correcta':'Revisemos esta respuesta'}</b><div>${esc(q.prompt)}</div><p style="margin:5px 0">${ok?'':`Tu elección: ${esc(q.options[chosen])}.<br>Respuesta correcta: ${esc(q.options[q.correct])}.<br>`}${esc(q.explanation)}</p></div>`;}).join('');}
function quiz(l,p){return `<div class="reader"><div class="eyebrow">AUTOEVALUACIÓN · 3 PREGUNTAS</div><h2>¿Podés usar lo que aprendiste?</h2><p class="muted">Elegí una respuesta por pregunta. Al corregir vas a ver la explicación. Son preguntas propias de práctica, no preguntas oficiales de certificación.</p><form id="quiz-form" novalidate>${l.quiz.map((q,i)=>`<fieldset class="quiz-question" data-question="${esc(q.id)}"><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((o,n)=>`<label class="quiz-option"><input type="radio" name="q-${esc(q.id)}" value="${n}" ${p.lastAnswers[q.id]===n?'checked':''}><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<div class="btn-row">${btn(p.attempts?'Volver a corregir':'Corregir mis respuestas','type="submit"',true)}<span class="small muted">${p.attempts?'Intentos: '+p.attempts+' · Mejor resultado: '+p.bestScore+'/3':'Sin intentos todavía'}</span></div></form><div id="quiz-result" class="quiz-result" role="region" aria-label="Resultado de la autoevaluación" tabindex="-1">${p.attempts?`<div class="score-large">${p.lastScore} / 3</div><p>${p.lastScore>=2?'Buen punto de partida. Explicá también por qué las otras opciones no sirven.':'Volvé a la lectura y buscá el concepto que te faltó.'}</p>${quizFeedback(l,p)}`:''}</div><div class="bottom-action"><span class="small muted">Un resultado repetido con las mismas preguntas no mide por sí solo dominio.</span>${btn('Escribir mi resumen →','data-step="notes"')}</div></div>`;}
function notes(l,p){return `<div class="reader"><div class="eyebrow">HACELO TUYO</div><h2>Tu explicación, con tus palabras.</h2><p>Imaginá que se lo explicás a alguien que recién empieza. Incluí qué problema resuelve, cómo funciona, un ejemplo propio, un error común y cómo lo comprobarías.</p><label class="field" for="lesson-notes">Mi resumen de esta clase</label><textarea id="lesson-notes" data-edit="notes" rows="11" maxlength="20000" placeholder="1. La idea principal…&#10;2. Cómo funciona…&#10;3. Mi ejemplo…&#10;4. Un error que voy a evitar…&#10;5. Cómo lo compruebo en una práctica…">${esc(p.notes)}</textarea><p class="field-hint">Se guarda mientras escribís. Lo vas a encontrar reunido en «Mi resumen».</p>${completion(p)}<div id="lesson-completion">${completionNotice(l,p)}</div><div class="bottom-action">${btn('Ver mi resumen completo','data-view="summary"')}${btn('Seguir estudiando →','data-action="next"',true)}</div></div>`;}
function completionNotice(l,p){return core.isComplete(p)?'<div class="notice"><strong>Clase completada según tu autoevaluación.</strong>La evidencia de la práctica queda disponible para revisión. Si algo todavía no te sale sin ayuda, retomalo antes del final.</div>':'<p class="field-hint">Para completar esta clase: registrá la lectura, escribí una respuesta de práctica de al menos 20 caracteres, marcá la práctica realizada y obtené 2 de 3 preguntas. El resumen te ayuda a consolidar.</p>';}
function summary(){const written=lessons.filter(l=>prog(l.id).notes.trim());return title('HECHO CON TUS PALABRAS','Mi resumen anual.','Acá se reúnen las notas de tus clases. Podés imprimirlas o descargarlas para preparar tu resumen final.')+`<div class="btn-row">${btn('Exportar resumen en copia JSON','data-action="summary-download"',true)}${btn('Imprimir / guardar PDF','data-action="print"')}</div>`+(written.length?written.map(l=>`<article class="summary-block"><div class="eyebrow">${esc(moduleOf(l.id).title)}</div><h2>${esc(l.title)}</h2><div class="summary-text">${esc(prog(l.id).notes)}</div><button class="btn link" data-lesson="${esc(l.id)}" data-open-notes="1">Editar esta nota →</button></article>`).join(''):'<div class="empty"><h2>Tu resumen empieza con la primera clase.</h2><p>Escribí en el paso «Mi resumen». La app va reuniendo tus explicaciones acá.</p>'+btn('Empezar a estudiar','data-action="continue"',true)+'</div>')+`<div class="notice"><strong>Comprobá relaciones entre materias.</strong>Al terminar, explicá el recorrido completo: equipo → proceso → red → datos → permisos → registro → recuperación. ${material('plantilla-resumen.html','Ver plantilla ampliada','')}</div>`;}
function makeDeck(filter='all'){deckFilter=filter;deck=lessons.filter(l=>filter==='all'||moduleOf(l.id).id===filter).flatMap(l=>l.cards.map(c=>({...c,lessonId:l.id,title:l.title})));cardIndex=0;revealed=false;}
function review(){if(!deck.length)makeDeck();revealed=false;const c=deck[cardIndex];return title('RECUERDO ACTIVO','Repasar sin mirar el apunte.','Leé la pregunta, intentá explicarla en voz alta y recién después mostrás la respuesta. Es una sesión libre de repaso.')+`<label for="deck-filter" class="field">Elegir materia</label><select id="deck-filter" class="filter"><option value="all" ${deckFilter==='all'?'selected':''}>Todas las materias · ${lessons.reduce((n,l)=>n+l.cards.length,0)} tarjetas</option>${modules.map(m=>`<option value="${esc(m.id)}" ${deckFilter===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select><div class="panel" style="margin-top:20px"><div class="section-title" style="margin-top:0"><span class="small muted" id="card-topic">${esc(c.title)}</span><span class="pill" id="card-counter">${cardIndex+1} / ${deck.length}</span></div><div class="flashcard" id="flashcard"><div class="flash-question">${esc(c.front)}</div></div><div class="btn-row" style="justify-content:center">${btn('← Anterior','data-action="card-prev"')}${btn('Mostrar respuesta','data-action="card-flip" id="card-flip" aria-controls="flashcard" aria-expanded="false"',true)}${btn('Siguiente →','data-action="card-next"')}</div><div class="small muted" style="text-align:center;margin-top:17px">Esta actividad no suma clases completadas. Si te cuesta, ${btn('volver a esa clase','data-action="card-lesson"')}.</div></div>`;}
function drawCard(){const c=deck[cardIndex],el=document.getElementById('flashcard');el.innerHTML=`<div class="flash-question">${esc(c.front)}</div>${revealed?`<div class="flash-answer">${esc(c.back)}</div>`:''}`;el.classList.toggle('answer',revealed);document.getElementById('card-topic').textContent=c.title;document.getElementById('card-counter').textContent=(cardIndex+1)+' / '+deck.length;const flip=document.getElementById('card-flip');flip.textContent=revealed?'Ocultar respuesta':'Mostrar respuesta';flip.setAttribute('aria-expanded',String(revealed));announce(revealed?'Respuesta: '+c.back:'Tarjeta '+(cardIndex+1)+' de '+deck.length+'. '+c.front);}
function finalView(){return title('CONECTAR TODO EL AÑO','El final integrador.','Un mismo caso para aplicar sistemas, Windows, Linux, redes, datos, programación y decisiones de seguridad.')+`<div class="notice"><strong>7 estaciones · 100 puntos · dos sesiones de 4 h 30 y una defensa de 30 min.</strong>La meta docente es 80/100, mínimos por estación y ejecución real. La app guarda tus borradores; la corrección de evidencias y la defensa requieren un tutor. No asigna una nota automática.</div><div class="btn-row">${material('final-anual/guia.txt','Guía completa en texto')}${material('final-anual/plantillas/rubrica.csv','Rúbrica de evaluación')}${material('final-anual/plantillas/informe-final.txt','Plantilla de informe')}</div><details><summary>Antes de empezar: escenario y preparación</summary><div class="station-content reader">${data.finalIntroHtml}</div></details>${data.stations.map(s=>`<details><summary>${esc(s.id.toUpperCase())} · ${esc(s.title)} <span class="station-meta">· ${s.points} puntos</span></summary><div class="station-content"><div class="reader">${s.html}</div><label class="field" for="station-${s.id}">Tu borrador y evidencia de ${s.id.toUpperCase()}</label><textarea id="station-${s.id}" data-final-station="${s.id}" rows="7" maxlength="20000" placeholder="Procedimiento, observaciones, archivos de evidencia y límites. Indicá si fue una ejecución real o análisis del caso.">${esc(state.final.stations[s.id]||'')}</textarea><p class="field-hint">Guardá los archivos de evidencia en tu carpeta. La app conserva este texto.</p></div></details>`).join('')}<section class="panel" style="margin-top:24px"><h2>Datos del caso</h2><p class="muted small">Son archivos sintéticos listos para trabajar. Usá la guía para preparar una copia y no sobrescribir tus intentos.</p><div class="btn-row">${data.finalFiles.map(f=>material('final-anual/datos/'+f,f)).join('')}</div><label class="field" for="final-notes">Conclusión de mi final</label><textarea id="final-notes" data-final-notes="1" rows="5" maxlength="20000" placeholder="Qué pude hacer sin ayuda, qué necesito reforzar y qué evidencia lo muestra…">${esc(state.final.notes)}</textarea><div class="bottom-action">${btn('Exportar borradores en copia JSON','data-action="final-download"',true)}${btn('Descargar copia de todo mi progreso','data-action="export"')}</div></section>`;}
function library(){return title('MATERIAL DE APOYO','Tu biblioteca, cuando la necesites.','Las clases ya traen su lectura. Acá tenés los cuadernos completos, los laboratorios con archivos y los recorridos de certificación.')+`<div class="library-grid">${data.library.map(b=>`<article class="panel"><div class="eyebrow">${esc(b.tag)}</div><h2>${esc(b.title)}</h2><p>${esc(b.description)}</p>${material(b.file,'Abrir '+b.title)}</article>`).join('')}</div><div class="notice"><strong>Certificaciones: un recorrido adicional.</strong>ISC2 CC, CCST, Security+, BTL1 y eJPT necesitan preparación específica y prácticas adicionales. Haber leído o completado la app no acredita aptitud para rendir. Los temarios y formatos se vuelven a verificar antes de reservar.</div><details><summary>Origen y límites del material</summary><p class="small muted" style="margin-top:15px">Las explicaciones, preguntas y prácticas son elaboración docente propia. Se leyeron tres programas PDF, guías HTML accesibles y un ejemplo Java. Quedan PDF internos, videos y secciones restringidas sin revisar. Gestión incluye ampliación propia; no se presenta como contenido leído del campus. Conservamos las guías originales y el progreso anterior.</p><div class="btn-row">${material('inventarios/so1.json','Inventario SO I')}${material('inventarios/so2-programacion.json','SO II y Programación')}${material('inventarios/telecom-datos.json','Telecomunicaciones y Datos')}${material('inventarios/sociedad-gestion.json','Sociedad y Gestión')}</div></details>`;}
function roadmapIds(){return data.roadmap.phases.flatMap(p=>p.tasks.map(t=>`base-${p.id}-${t.id}`)).concat(data.roadmap.certifications.flatMap(c=>c.steps.map(s=>`cert-${c.id}-${s.id}`)));}
function roadmapCounts(){const ids=roadmapIds(),completed=ids.filter(id=>state.roadmap.tasks[id]===true).length;return {total:ids.length,completed,percent:ids.length?Math.round(completed/ids.length*100):0};}
function roadmapMeter(){const s=roadmapCounts();return `<div class="roadmap-meter"><div><strong>${s.completed} de ${s.total}</strong><span> pasos registrados · se guardan con tu progreso</span></div><div class="track" role="progressbar" aria-label="Pasos del roadmap registrados" aria-valuemin="0" aria-valuemax="${s.total}" aria-valuenow="${s.completed}"><span style="width:${s.percent}%"></span></div></div>`;}
function roadCheck(id,title,detail){return `<label class="roadmap-check" for="roadmap-${id}"><input id="roadmap-${id}" type="checkbox" data-roadmap-task="${id}" ${state.roadmap.tasks[id]?'checked':''}><span><strong>${esc(title)}</strong>${detail?`<span class="roadmap-detail">${esc(detail)}</span>`:''}</span></label>`;}
function resourceLink(link){const url=new URL(link.url);if(url.protocol!=='https:')throw new Error('Enlace de recurso no válido.');return `<a class="resource-link" href="${esc(url.href)}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(link.label)}</strong><span>${esc(link.description)}</span><span class="resource-access">${esc(link.access)} · ${link.kind==='official'?'Fuente oficial':'Práctica externa'} · abre otra pestaña</span></span><span aria-hidden="true">↗</span></a>`;}
function roadmapView(){
 const r=data.roadmap;
 return title('TU RUTA HACIA DICIEMBRE DE 2026','Del fundamento a la certificación.','Primero una base sólida. Después, una ruta específica con prácticas, evidencias y criterios para decidir cuándo rendir.')+warning()+`<section class="roadmap-intro"><div><span class="pill green">5 OBJETIVOS · UN RECORRIDO COMÚN</span><h2>Elegí con evidencia, avanzá con un plan.</h2><p>${esc(r.intro)}</p><p class="small muted">Orientación propia · enlaces y datos revisados el ${esc(r.verifiedAt)}. Los sitios externos necesitan conexión; algunos requieren cuenta o pago.</p></div><div class="roadmap-legend"><span class="cert-track">BASE</span><span aria-hidden="true">→</span><span class="cert-track">RUTA</span><span aria-hidden="true">→</span><span class="cert-track">PRÁCTICA AUTÓNOMA</span></div></section><div id="roadmap-progress" aria-live="off">${roadmapMeter()}</div>
 <section class="notice"><h2>Del plan a una capacidad concreta</h2><p>La matriz de competencias te muestra qué explicar, qué ejecutar y qué evidencia conservar para cada objetivo. Las salas te permiten ponerlo en práctica.</p><div class="btn-row">${btn('Qué necesito saber','data-view="competencies"',true)}${btn('Explorar salas prácticas','data-view="environments"')}</div></section><p id="control-error" class="save-error" role="alert" hidden></p><div class="section-title"><h2>01 · Tu base y tus hitos</h2><a href="#cert-routes">Ir a las cinco certificaciones ↓</a></div>
 <div class="roadmap-stages">${r.phases.map((phase,i)=>`<section class="roadmap-stage"><div class="stage-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</div><div class="stage-content"><span class="pill">${esc(phase.timeframe)}</span><h3>${esc(phase.title)}</h3><p>${esc(phase.goal)}</p>${phase.tasks.map(t=>`<div class="roadmap-task">${roadCheck(`base-${phase.id}-${t.id}`,t.title,t.detail)}<div class="quick-links">${(t.lessonIds||[]).map(id=>{const l=lessonById(id);return l?btn(esc(l.title),`data-lesson="${esc(id)}"`):'';}).join('')}${t.material?material(t.material,'Material de práctica'):''}</div></div>`).join('')}<div class="checkpoint"><strong>Antes de avanzar, reuní esta evidencia</strong><ul>${phase.evidence.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div></div></section>`).join('')}</div>
 <div class="section-title" id="cert-routes"><h2>02 · Tus rutas de certificación</h2></div><p class="muted">No hace falta comprar o rendir las cinco juntas. Las casillas registran tu trabajo; la preparación se comprueba con evidencias y una evaluación nueva.</p>
 <div class="cert-grid">${r.certifications.map((cert,i)=>`<article class="cert-card" id="cert-${esc(cert.id)}"><div class="card-top"><span class="cert-track">${esc(cert.track)}</span><span class="cert-number" aria-hidden="true">0${i+1}</span></div><h3>${esc(cert.name)}</h3><p>${esc(cert.summary)}</p><div class="notice">${esc(cert.versionNote)}</div><details><summary>Qué priorizar y cómo practicar</summary><ul>${cert.priorities.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="cert-steps">${cert.steps.map((s,j)=>`<section class="cert-step">${roadCheck(`cert-${cert.id}-${s.id}`,`${j+1}. ${s.title}`,s.detail)}<p><strong>Práctica:</strong> ${esc(s.practice)}</p><p><strong>Evidencia:</strong> ${esc(s.evidence)}</p></section>`).join('')}</div><div class="checkpoint"><strong>Criterios para considerar una fecha de examen</strong><ul>${cert.readiness.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></div><label class="field" for="cert-notes-${cert.id}">Mis brechas y próximo paso para ${esc(cert.name)}</label><textarea id="cert-notes-${cert.id}" data-roadmap-note="${cert.id}" rows="4" maxlength="20000" placeholder="Qué ya puedo demostrar, qué me falta y cuál va a ser mi próxima práctica…">${esc(state.roadmap.notes[cert.id]||'')}</textarea></details><div class="roadmap-links"><h4>Enlaces directos</h4>${cert.links.map(resourceLink).join('')}</div></article>`).join('')}</div>
 <div class="notice"><strong>Una fecha orienta; la evidencia decide.</strong>Los porcentajes de simulacros y los hitos de este recorrido son criterios docentes propios. No equivalen a la puntuación oficial ni garantizan aprobar. Revisá código, idioma, reglas y temario vigentes antes de reservar.</div><details><summary>Fuentes y fecha de revisión</summary><p>Revisado el ${esc(r.verifiedAt)}. Los enlaces oficiales son la referencia para cambios de versión, condiciones y acceso.</p><ul>${r.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} <span class="small">(otra pestaña)</span></a></li>`).join('')}</ul></details>`;
}

function home(){const s=core.summary(state,curriculum),next=core.nextLesson(state,curriculum)||lessons[0];return title('APRENDER CON CRITERIO','Tu campus. Tu próximo paso.','Una base sólida en sistemas, redes y ciberdefensa, construida con práctica y tus propias explicaciones.')+`<section class="hero"><div><span class="pill">RECORRIDO ANUAL · 24 CLASES</span><h2>Entender cómo funciona.<br>Aprender a protegerlo.</h2><p>Leé un concepto, ponelo a prueba y conservá la evidencia. Todo tu recorrido está disponible en este equipo.</p><div class="btn-row">${btn('Continuar estudiando →',`data-lesson="${esc(next.id)}"`,true)}${btn('Explorar salas prácticas','data-view="environments"')}</div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 220 220"><circle cx="110" cy="110" r="95"/><circle cx="110" cy="110" r="70"/><path d="M110 38 173 67v70l-63 45-63-45V67Z"/><path d="m80 107 22 22 42-47"/></svg><span>SISTEMAS · REDES · CRITERIO</span></div></section>${window.OnboardingHub&&!labData['professional-onboarding']?.completed&&!labData['professional-onboarding']?.skipped?'<section class="notice"><h2>Tu campus, en tres pasos</h2><p>Elegí tu prioridad y un entorno viable para empezar.</p><button class="btn primary" data-view="onboarding">Preparar mi campus</button></section>':''}${professional()?.todayPanel()||''}<div class="stats"><section><strong>${s.completed}<small> / 24</small></strong><span>Clases completadas</span></section><section><strong>3 + 8</strong><span>Salas y ejercicios</span></section><section><strong>27</strong><span>Competencias por trabajar</span></section><section><strong>5</strong><span>Rutas de certificación</span></section></div><div class="section-title"><div><span class="eyebrow">PLAN DE ESTUDIO</span><h2>Una materia a la vez.</h2></div>${btn('Ver todas las clases →','data-view="route"')}</div><div class="module-grid">${modules.map(moduleCard).join('')}</div><section class="panel split"><div><span class="eyebrow">RECUERDO ACTIVO</span><h2>Explicalo sin mirar.</h2><p>Probá tus conocimientos con 48 tarjetas de todas las materias.</p>${btn('Repasar tarjetas','data-view="review"')}</div><div><span class="eyebrow">PROYECCIÓN PROFESIONAL</span><h2>Tu ruta de certificación.</h2><p>Conectá la base del año con prácticas, brechas y próximos pasos.</p>${btn('Qué necesito saber','data-view="competencies"')}${btn('Abrir roadmap','data-view="roadmap"')}</div></section><p class="field-hint">El progreso refleja estudio y autoevaluación personal. Las prácticas abiertas y el final necesitan revisión docente; estos registros no acreditan títulos ni certificaciones.</p>`;}
function profileForm(){return `<form id="create-profile-form" class="panel"><label class="field" for="profile-name">Nombre del perfil</label><p class="field-hint" id="profile-hint">Usá tu nombre o un apodo. No se necesita correo ni contraseña.</p><input id="profile-name" name="profile-name" maxlength="80" required autocomplete="off" aria-describedby="profile-hint"><div class="btn-row">${btn('Crear perfil','type="submit"',true)}</div></form>`;}
function profilesView(){return title('ESTUDIO EN ESTE EQUIPO','Perfiles locales','Cada perfil conserva sus notas, avance y laboratorios. Son espacios de estudio, no cuentas ni una barrera de acceso entre personas del mismo equipo.')+`<div class="profile-grid">${profiles.map(p=>`<article class="panel"><span class="avatar" aria-hidden="true">${esc(p.name.slice(0,1).toUpperCase())}</span><h2>${esc(p.name)}</h2><p>${profile?.id===p.id?'Perfil activo':'Disponible en este equipo'}</p>${profile?.id!==p.id?btn('Abrir perfil',`data-select-profile="${esc(p.id)}"`,true):`<form id="rename-profile-form"><label class="field" for="rename-profile">Cambiar nombre</label><input id="rename-profile" value="${esc(p.name)}" maxlength="80" required>${btn('Guardar nombre','type="submit"')}</form>`}</article>`).join('')}</div><h2>Otro espacio de estudio</h2>${profileForm()}<div class="notice">Los datos se guardan en la carpeta de usuario de la aplicación, fuera de su instalación. Para trasladarlos a otro equipo, exportá una copia desde Ajustes.</div>`;}
function settings(){const p=effectivePreferences(),select=(key,label,options)=>`<div class="setting-control"><label for="pref-${key}">${label}</label><select id="pref-${key}" data-preference="${key}">${options.map(([value,text])=>`<option value="${value}" ${p[key]===value?'selected':''}>${text}</option>`).join('')}</select></div>`;return title('LECTURA Y DATOS LOCALES','Un campus a tu medida.','Las preferencias se conservan en tu perfil junto con el estudio.')+`<section class="panel"><h2>Lectura y accesibilidad</h2><div class="access-grid">${select('theme','Apariencia',[['system','La del sistema'],['light','Claro'],['dark','Oscuro']])}${select('font','Tamaño del texto',[['standard','Estándar'],['large','Grande'],['xl','Muy grande']])}${select('contrast','Contraste',[['standard','Estándar'],['high','Alto contraste']])}${select('spacing','Espaciado',[['standard','Estándar'],['wide','Amplio']])}${select('motion','Movimiento',[['system','Respetar el sistema'],['reduced','Reducir movimiento']])}<label class="checkline"><input type="checkbox" data-preference="focusMode" ${p.focusMode?'checked':''}>Modo de concentración</label></div>${btn('Restablecer apariencia','data-action="preferences-reset"')}</section><section class="panel"><h2>Una copia de tu recorrido</h2><p>Exportá el perfil con sus clases, notas, roadmap y laboratorios. También podés importar una copia anterior de Academia de Ciberdefensa desde un archivo elegido por vos.</p><div class="btn-row">${btn('Exportar copia del perfil','data-action="export"',true)}${btn('Importar y reemplazar progreso…','data-action="confirm-import"')}</div><p class="field-hint">La importación reemplaza el progreso del perfil activo. Conservá primero una copia si querés volver atrás.</p></section><section class="panel"><h2>Aplicación y actualizaciones</h2><p>Versión ${esc(info.version||'—')} · ${info.packaged?'Instalación de escritorio':'Modo de desarrollo'}</p><p>El estudio funciona sin conexión. Las fuentes externas y la búsqueda de actualizaciones necesitan Internet.</p><p id="settings-update">${esc(updateStatus.message||'Las actualizaciones se consultan al abrir la aplicación.')}</p>${btn('Buscar actualizaciones','data-action="check-update"')}<p class="field-hint">Las actualizaciones descargadas se aplican al reiniciar después de guardar el trabajo.</p></section>`;}
function logTable(){const filters={},source=document.getElementById('log-source-filter')?.value.trim(),user=document.getElementById('log-user-filter')?.value.trim();if(source)filters.sourceIp=source;if(user)filters.username=user;const rows=window.LabEngine.queryLog(filters);return `<p class="field-hint" role="status">${rows.length} eventos encontrados</p><div class="log-table-wrap"><table class="log-table"><caption>Eventos sintéticos del caso · UTC</caption><thead><tr>${['ID','Momento','Origen','Cuenta','Evento','Resultado','Detalle'].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${[r.id,r.timestamp,r.sourceIp,r.username,r.event,r.outcome,r.detail].map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function logTools(){return `<section aria-label="Evidencia de eventos"><h3>Registro del caso</h3><div class="log-filters"><label for="log-source-filter">Filtrar por IP de origen<input id="log-source-filter" type="search" placeholder="IP exacta" aria-controls="log-results"></label><label for="log-user-filter">Filtrar por cuenta<input id="log-user-filter" type="search" placeholder="Cuenta exacta" aria-controls="log-results"></label></div><div id="log-results">${logTable()}</div></section>`;}
function labsView(){const catalog=window.LabEngine?.catalog||[];return title('DEL CONCEPTO A LA EVIDENCIA','Laboratorios de ciberdefensa.','Ocho situaciones para practicar, equivocarte y explicar tus decisiones con datos sintéticos.')+`<div class="notice"><strong>Un entorno de aprendizaje en este equipo.</strong>La terminal es una simulación; SQL ejecuta consultas reales en una base aislada. Las prácticas guiadas Windows y Kali usan tu propio entorno y se identifican por separado.</div><div class="module-grid">${catalog.map((l,i)=>`<article class="panel lab-card"><div class="card-top">${icon('labs')}<span class="pill">${l.id==='sql-investigation'?'SQL REAL AISLADO':'SIMULACIÓN OFFLINE'}</span></div><span class="eyebrow">LAB ${String(i+1).padStart(2,'0')}</span><h2>${esc(l.title)}</h2><p>${esc(l.description||l.objective||'')}</p><p class="small muted">${labData[l.id]?.attempts?'Intentos: '+labData[l.id].attempts:'Todavía sin intentos'}</p>${btn('Abrir laboratorio →',`data-lab="${esc(l.id)}"`,true)}</article>`).join('')}</div><section class="panel"><h2>Práctica guiada en tus sistemas</h2><p>Continuá en Windows o en una máquina virtual Kali de laboratorio. Abrí la guía y guardá una copia de los archivos antes de trabajar. Estas prácticas requieren ejecutar y comprobar los pasos en esos entornos.</p>${material('repaso-anual.html','Guía de sistemas y redes')}${material('final-anual/guia.txt','Guía Windows y Linux del final')}${btn('Ver recursos generales de este equipo','data-action="system-info"')}${systemInfo?`<p role="status">${esc(systemInfo.platform)} ${esc(systemInfo.release)} · ${systemInfo.cpuCount} CPU lógicas · ${systemInfo.totalMemoryGiB} GiB de memoria</p>`:''}</section>`;}
function labFormFields(id){const saved=labData[id]?.answers||{};const field=(key,label,value='')=>`<label class="field" for="lab-${key}">${esc(label)}</label><input id="lab-${key}" name="${key}" value="${esc(saved[key]??value)}" maxlength="20000">`;const select=(key,label,opts)=>`<label class="field" for="lab-${key}">${esc(label)}</label><select id="lab-${key}" name="${key}"><option value="">Elegí una opción</option>${opts.map(([v,t])=>`<option value="${v}" ${saved[key]===v?'selected':''}>${esc(t)}</option>`).join('')}</select>`;switch(id){case 'linux-permissions':return `<pre class="terminal" id="terminal-output" tabindex="0" aria-label="Salida de terminal simulada">${esc(labOutput||'Terminal virtual. Escribí help para ver los comandos disponibles.')}</pre><label class="field" for="lab-command">Comando de la terminal virtual</label><div class="command-row"><input id="lab-command" name="command" autocomplete="off" spellcheck="false" placeholder="help">${btn('Ejecutar comando','data-action="run-command" type="button"')}</div>`;case 'sql-investigation':return `<label class="field" for="lab-query">Consulta SQL</label><textarea class="code-editor" id="lab-query" name="query" rows="7" spellcheck="false" maxlength="12000">${esc(saved.query||activeLab.defaultQuery||'SELECT * FROM events LIMIT 20;')}</textarea><p class="field-hint">Base sintética aislada. La consulta no accede a archivos del equipo.</p><pre id="sql-output" class="terminal" tabindex="0" aria-label="Resultado SQL">${esc(labOutput||'Volvé a ejecutar la consulta para ver sus filas y evaluar el intento. La tabla de resultados no se guarda en el perfil.')}</pre>`;case 'windows-acl':return select('principal','Grupo que necesita acceso',[['Soporte','Soporte'],['Todos','Todos'],['Administradores','Administradores']])+select('permission','Permiso mínimo',[['read','Lectura'],['modify','Modificar'],['full','Control total']])+select('inheritance','Regla amplia heredada',[['remove','Quitar la regla amplia heredada'],['keep','Conservar']]);case 'ipv4-subnet':return `<p>Analizá la dirección <code>192.0.2.131/26</code>.</p>`+field('network','Dirección de red')+field('broadcast','Broadcast')+field('firstHost','Primer host')+field('lastHost','Último host')+field('usableHosts','Cantidad de hosts utilizables');case 'incident-logs':return field('sourceIp','IP de origen')+field('account','Cuenta afectada')+field('evidenceIds','IDs de eventos que sustentan la conclusión (separados por coma)');case 'phishing-triage':return select('verdict','Clasificación',[['phishing','Phishing'],['legitimate','Legítimo']])+select('signal','Señal con mayor valor de evidencia',[['domain','Dominio de destino'],['logo','Logo'],['urgency','Urgencia']])+select('action','Siguiente acción',[['report','Reportar por el canal definido'],['reply','Responder'],['open','Abrir el enlace']]);case 'integrity-hash':return `<p>Texto de la muestra (LF final incluido):</p><pre>${esc(activeLab.sample||'')}</pre><p>SHA-256 de referencia:</p><pre>${esc(activeLab.referenceDigest||'')}</pre>${btn('Calcular SHA-256 de la muestra','data-action="hash-sample" type="button"')}<output id="hash-output" class="summary-text"></output>`+field('digest','SHA-256 calculado')+select('decision','Comparación con la referencia',[['match','Coincide'],['mismatch','No coincide']]);case 'recovery-evidence':return field('order','Orden de acciones (IDs separados por coma)')+select('source','Fuente para recuperar',[['verified-backup','Copia verificada'],['original','Original del incidente']])+select('validation','Validación final',[['hash-and-service','Integridad y servicio'],['service-only','Solo servicio']]);default:return '';}}
function labView(){const id=activeLab.id,saved=labData[id]||{};return `<button class="back" data-view="labs">← Todos los laboratorios</button>`+title('LABORATORIO · ENTORNO LOCAL',activeLab.title,activeLab.description||activeLab.objective||'')+`<section class="panel reader"><span class="pill">${id==='sql-investigation'?'EJECUCIÓN SQL REAL · BASE AISLADA':'SIMULACIÓN EDUCATIVA'}</span><h2>Tu misión</h2><p class="scenario">${esc(activeLab.scenario||activeLab.instructions||activeLab.objective||'Resolvé el caso y reuní evidencia para justificar tu respuesta.')}</p><div class="lab-meta"><span>${esc(activeLab.environment||'')}</span><span>${esc(activeLab.duration||'')}</span></div>${activeLab.steps?`<ol>${activeLab.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:''}${activeLab.limitation?`<p class="field-hint">${esc(activeLab.limitation)}</p>`:''}<div class="btn-row">${(activeLab.materials||[]).map(file=>material(file,'Abrir guía de este laboratorio')).join('')}</div>${id==='incident-logs'?logTools():''}${Array.isArray(activeLab.tasks)?`<ul>${activeLab.tasks.map(t=>`<li>${esc(typeof t==='string'?t:t.title||t.description)}</li>`).join('')}</ul>`:''}${activeLab.logs?`<pre class="terminal">${esc(typeof activeLab.logs==='string'?activeLab.logs:JSON.stringify(activeLab.logs,null,2))}</pre>`:''}<form id="lab-form">${labFormFields(id)}<div class="btn-row">${btn(id==='sql-investigation'?'Ejecutar consulta y evaluar':'Comprobar mi intento','type="submit"',true)}</div></form><div id="lab-feedback" tabindex="-1" role="region" aria-label="Devolución del intento">${labResult?`<div class="notice"><strong>${labResult.passed?'Objetivo alcanzado':'Revisá tu evidencia'} · ${labResult.score}/${labResult.total}</strong><ul>${labResult.feedback.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:''}</div><label class="field" for="lab-notes">Mi procedimiento y evidencia</label><textarea id="lab-notes" data-lab-notes="${esc(id)}" maxlength="20000" rows="6">${esc(saved.notes||'')}</textarea><p class="field-hint">Anotá qué probaste, qué observaste y qué queda pendiente. Se guarda en tu perfil.</p>${saved.evidence?`<details><summary>Última evidencia registrada</summary><pre>${esc(JSON.stringify(saved.evidence,null,2))}</pre></details>`:''}</section>`;}
function disposeHubs(){realEnvironmentView?.dispose();missionView?.dispose();competencyView?.dispose();professionalView?.dispose();recoveryView?.dispose();}
async function saveProfessionalRecord(key,record,expectedId,{retry=false}={}){if(!profile||profileBusy||profile.id!==expectedId)throw new Error('El perfil cambió o hay una operación de perfil pendiente. El registro no se guardó.');if(!['professional-learning','professional-onboarding','preparation-ledger','independent-assessment','packet-casework','objective-progress','forensic-casework','tutor-reviews'].includes(key)&&!/^(practice|campaign)-[a-z0-9-]{1,80}$/.test(key))throw new Error('Registro de estudio inválido.');if(key==='forensic-casework'&&window.CampusForensicCore)window.CampusForensicCore.normalize(record);if(key==='objective-progress'&&window.CampusObjectivesCore)window.CampusObjectivesCore.validateRecord(record);if(retry)saveError=null;labData={...labData,[key]:clone(record)};persist();await flush();return true;}
function professional(){if(!professionalView&&window.ProfessionalShell)professionalView=window.ProfessionalShell.create({desktop,getProfileId:()=>profile?.id||null,getProfileEpoch:()=>profileGeneration,getLabs:()=>labData,getStudy:()=>state,saveLab:saveProfessionalRecord,applyPlan:configureLearning,openLesson,openMission,openMaterial:(file,anchor)=>desktop.openMaterial(anchor?{file,anchor}:file),openPractice:openSystemPractice,openVM:openVirtualMachine,navigate,announce,onEvidenceChange:updateChrome,runProfileOperation:profileOperation,onProfileUpdated:applyExternalProfile});return professionalView;}
async function configureLearning(patch){const r=window.ProfessionalCore.normalize(labData['professional-learning']);return saveProfessionalRecord('professional-learning',window.ProfessionalCore.updateSettings(r,{...r.settings,...patch}),profile.id);}
function recoveryPage(){if(!recoveryView&&window.RecoveryHub)recoveryView=window.RecoveryHub.create({desktop,getEpoch:()=>profileGeneration,getProfileId:()=>profile?.id,onRecover:id=>restoreLocalData(()=>desktop.recoverStore(id)),onExternalRestore:()=>restoreLocalData(()=>desktop.recoverFromBackup()),announce});return recoveryView?.render()||title('RECUPERACIÓN','Actualizá el campus.','No se pudieron cargar las herramientas de recuperación.');}
async function restoreLocalData(action){return profileOperation(async()=>{const result=await action();if(result.canceled)return result;if(result.profile)adopt(result.profile);else{disposeHubs();profileGeneration++;profile=null;state=core.createState(curriculum);labData={};changeNumber=0;savedNumber=0;saveError=null}profiles=await desktop.listProfiles();view='home';render(true);return result;},{discard:!profile});}
function applyExternalProfile(next){if(next&&next.id===profile?.id){adopt(next);render(true);}}
function professionalPage(target){return professional()?.render(target)||title('CAMPUS PROFESIONAL','Actualizá el campus.','Abrí la versión de escritorio para usar el plan, las prácticas y el portafolio.');}
function openSystemPractice(id,campaign=false){navigate('systems');professional()?.openSystem(id,campaign);}
function openVirtualMachine(templateId='windows'){navigate('vms');const target=[...main.querySelectorAll('[data-vm-template]')].find(el=>el.dataset.vmTemplate===templateId)?.querySelector('h2');if(target){target.tabIndex=-1;target.focus();target.scrollIntoView?.({block:'start'});}}
let searchResults=[],modalReturnFocus=null;
function globalSearch(){if(!profile)return;modalReturnFocus=document.activeElement;const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal global-search-modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">Buscar en todo el campus</h2><label class="field" for="campus-global-query">Tema, práctica o competencia</label><input id="campus-global-query" type="search" maxlength="300" autocomplete="off" aria-controls="campus-search-results" aria-describedby="campus-search-status"><p id="campus-search-status" class="field-hint" role="status">Buscá entre clases, salas, competencias, prácticas y biblioteca.</p><div id="campus-search-results" class="search-results"></div><button class="btn" data-action="cancel-modal">Cerrar búsqueda</button></section></div>`;document.getElementById('campus-global-query').focus();searchResults=[];}
function runGlobalSearch(query){const engine=window.CampusSearch,index=engine?.buildIndex({curriculum,competencies:window.CAMPUS_COMPETENCIES,missions:window.CAMPUS_MISSIONS,practices:window.CAMPUS_SYSTEM_PRACTICES,library:data.library,assessments:window.CAMPUS_ASSESSMENTS},window.CAMPUS_OBJECTIVES);searchResults=engine?engine.search(index,query):[];const labels={objective:'Objetivo del examen',assessment:'Caso práctico',page:'Sección del campus',lesson:'Clase',competency:'Competencia',mission:'Sala práctica',practice:'Práctica de sistemas',campaign:'Campaña',material:'Biblioteca'};document.getElementById('campus-search-results').innerHTML=searchResults.map((item,index)=>`<button type="button" class="search-result" data-search-index="${index}"><strong>${esc(item.title)}</strong><small>${esc(labels[item.kind]||'Recurso')} · ${esc(item.description.slice(0,170))}</small></button>`).join('');document.getElementById('campus-search-status').textContent=query.trim()?`${searchResults.length} resultados. Elegí uno para abrirlo.`:'Escribí un tema para empezar.';}
function selectSearchResult(index){if(!Number.isSafeInteger(index)||!searchResults[index])return;const result=searchResults[index];closeModal();switch(result.kind){case 'objective':navigate('objectives');{const select=main.querySelector('[name="certificationId"]');if(select){select.value=result.certificationId;select.dispatchEvent(new Event('change',{bubbles:true}));}const row=[...main.querySelectorAll('details[data-objective-id]')].find(el=>el.dataset.objectiveId===result.id);if(row){row.open=true;row.dispatchEvent(new Event('toggle'));row.querySelector('summary')?.focus();row.scrollIntoView?.({block:'start'});}else toast('Terminá el borrador pendiente para cambiar el objetivo.');}break;case 'assessment':openAssessmentCase(result.id);break;case 'page':navigate(result.id);break;case 'lesson':openLesson(result.id);break;case 'mission':openMission(result.id);break;case 'practice':openSystemPractice(result.id);break;case 'campaign':openSystemPractice(result.id,true);break;case 'material':desktop.openMaterial(result.id).catch(error=>toast(error.message));break;case 'competency':navigate('competencies');{const select=main.querySelector('[data-competency-certification]');if(select){select.value=result.certificationId;select.dispatchEvent(new Event('change',{bubbles:true}));}const entry=[...main.querySelectorAll('[data-competency-skill]')].find(el=>el.dataset.competencySkill===result.id);if(entry){entry.tabIndex=-1;entry.focus();entry.scrollIntoView?.({block:'start'});}}break;}}
function openAssessmentCase(id){if(profileBusy)return false;if(professional()?.openAssessment(id)){navigate('assessment');return true;}toast('El caso no está disponible en esta versión.');return false;}
function openMission(id){view='environments';render(true);missionView?.openRoom(id);}
function environmentsView(){
 if(!missionView&&window.MissionHub)missionView=window.MissionHub.create({desktop,getProfileId:()=>profile?.id||null,getProgress:roomId=>clone(labData['mission-'+roomId]||{}),saveProgress:async(roomId,record,expectedProfileId,{retry=false}={})=>{if(!profile||profileBusy||profile.id!==expectedProfileId)throw new Error('El perfil cambió o hay una operación de perfil pendiente. El registro no se guardó.');if(retry)saveError=null;labData={...labData,['mission-'+roomId]:clone(record)};persist();await flush();return true;},openLesson,openMaterial:file=>desktop.openMaterial(file),announce});
 if(missionView)return missionView.render();
 if(!realEnvironmentView&&window.RealEnvironments)realEnvironmentView=window.RealEnvironments.create({desktop,getProfileId:()=>profile?.id||null,escape:esc,announce});
 return realEnvironmentView?realEnvironmentView.render():title('SALAS PRÁCTICAS','El módulo no está disponible.','Reiniciá la aplicación desde su instalación actualizada.');
}
function competenciesView(){if(!competencyView&&window.CompetencyHub)competencyView=window.CompetencyHub.create({data:window.CAMPUS_COMPETENCIES,getStudy:()=>state,getLabs:()=>labData,openLesson,openMission,navigate,announce});return competencyView?competencyView.render():title('COMPETENCIAS','Qué necesito saber.','La matriz de objetivos se carga desde la aplicación actualizada.');}
function render(focus=false){disposeHubs();applyPreferences();const views={recovery:recoveryPage,home,route,lesson,summary,review,final:finalView,library,settings,roadmap:roadmapView,profiles:profilesView,labs:labsView,lab:labView,environments:environmentsView,competencies:competenciesView,forensics:()=>professionalPage('forensics'),topology:()=>professionalPage('topology'),objectives:()=>professionalPage('objectives'),tutor:()=>professionalPage('tutor'),merge:()=>professionalPage('merge'),'packet-analysis':()=>professionalPage('packet-analysis'),preparation:()=>professionalPage('preparation'),assessment:()=>professionalPage('assessment'),'learning-history':()=>professionalPage('learning-history'),onboarding:()=>professionalPage('onboarding'),learning:()=>professionalPage('learning'),diagnostic:()=>professionalPage('diagnostic'),exam:()=>professionalPage('exam'),calendar:()=>professionalPage('calendar'),'spaced-review':()=>professionalPage('spaced-review'),systems:()=>professionalPage('systems'),vms:()=>professionalPage('vms'),portfolio:()=>professionalPage('portfolio')};document.getElementById('navigation').innerHTML=profile?[['home','Inicio'],['onboarding','Guía de inicio'],['learning','Mi plan'],['preparation','Certificaciones'],['objectives','Objetivos por examen'],['assessment','Evaluación práctica'],['route','Cursos'],['systems','Sistemas y casos'],['environments','Salas prácticas'],['packet-analysis','Análisis de paquetes'],['labs','Entrenamiento'],['vms','Escritorios VM'],['topology','Red de práctica'],['forensics','Forense y SIEM'],['tutor','Devoluciones'],['merge','Combinar equipos'],['portfolio','Mi portafolio'],['competencies','Qué necesito saber'],['roadmap','Roadmap'],['summary','Mi resumen'],['final','Final integrador'],['library','Biblioteca'],['profiles','Perfiles'],['recovery','Copias y recuperación'],['settings','Ajustes']].map(([id,label])=>`<button class="nav-item" data-view="${id}">${icon(id)}<span>${label}</span></button>`).join(''):'';main.innerHTML=view==='recovery'?recoveryPage():profile?(views[view]||home)():title('BIENVENIDO A TU CAMPUS','Crear perfil de estudio','El campus funciona sin conexión. Elegí un nombre para conservar tus clases, notas y laboratorios en este equipo.')+profileForm()+`<div class="btn-row">${btn('Recuperar un respaldo JSON existente', 'data-view="recovery"')}</div>`+(profiles.length?'<section class="panel"><h2>Perfiles disponibles en este equipo</h2><div class="btn-row">'+profiles.map(p=>btn(esc(p.name),'data-select-profile="'+esc(p.id)+'"')).join('')+'</div></section>':'')+`<p class="field-hint">Sin cuentas online. No se envía tu progreso a un servidor. Cada persona con acceso al equipo puede abrir los perfiles locales.</p>`;if(view==='recovery')recoveryView?.mount(main);if(profile&&view==='environments'){if(missionView)missionView.mount(main);else realEnvironmentView?.mount(main);}if(profile&&view==='competencies')competencyView?.mount(main);if(profile&&['onboarding','learning','diagnostic','exam','calendar','spaced-review','systems','vms','portfolio','preparation','assessment','learning-history','packet-analysis','tutor','merge','objectives','topology','forensics'].includes(view))professional()?.mount(main);if(profile&&view==='labs'){main.querySelector('.page-heading')?.insertAdjacentHTML('afterend',`<section class="notice"><h2>Salas con entornos que podés encender</h2><p>Practicá ataque web, investigación defensiva y bases de datos con tareas, pistas y evidencias. El campus comprueba Docker antes de iniciar un entorno.</p>${btn('Explorar salas prácticas →','data-view="environments"',true)}</section>`);}main.querySelectorAll('h1').forEach(el=>el.tabIndex=-1);updateChrome();lockProfileControls();if(focus)focusElement(typeof focus==='string'?focus:null);}
function renderUpdate(s){updateStatus=s||{};const el=document.getElementById('update-banner');el.hidden=!s||s.status==='idle'||s.status==='not-available';el.innerHTML=s?`${esc(s.message||({checking:'Buscando actualizaciones…',available:'Hay una nueva versión. Descargando…',downloading:'Descargando actualización',downloaded:'Actualización lista para instalar',error:'No se pudo comprobar la actualización. Podés seguir estudiando sin conexión.'})[s.status]||'')}${s.version?' · '+esc(s.version):''}${Number.isFinite(s.percent)?' · '+Math.round(s.percent)+'%':''}${s.status==='downloaded'?btn('Guardar y reiniciar','data-action="install-update"'):''}`:'';const detail=document.getElementById('settings-update');if(detail)detail.textContent=s.message||'Estado actualizado.';}
async function executeAction(action){switch(action){case 'global-search':globalSearch();break;case 'export-portfolio-pdf':case 'export-portfolio-html':{const expected=profile.id;await flush();if(profile.id!==expected)return;const result=await desktop.exportPortfolio({profileId:expected,format:action.endsWith('pdf')?'pdf':'html'});if(!result.canceled)toast('Portafolio exportado. Revisá el documento antes de compartirlo.');}break;case 'exit-focus':changePreferences({focusMode:false});break;case 'preferences-reset':changePreferences(core.createState(curriculum).preferences);render(true);break;case 'retry-save':saveError=null;await flush();toast('Cambios guardados en este equipo.');break;case 'reload-profile':modal('Recuperar la versión guardada','Se descartarán los cambios pendientes de esta sesión y se volverá a abrir el archivo guardado del perfil. Copiá tus textos antes de continuar.','apply-reload','Descartar pendientes y recuperar');break;case 'apply-reload':await profileOperation(async()=>{adopt(await desktop.selectProfile(profile.id));closeModal();render(true);},{discard:true});break;case 'cancel-modal':closeModal();break;case 'discard-close':await beforeClose({discard:true});break;case 'confirm-discard-evidence':modal('Descartar textos rechazados','Se perderán únicamente los textos que superaron los límites. Las versiones válidas se conservan. Copiá tu texto antes de continuar.','discard-evidence','Descartar textos rechazados');break;case 'discard-evidence':professionalView?.discardRejectedEvidence();closeModal();render();break;case 'export':await flush();await desktop.exportBackup(profile.id);break;case 'confirm-import':modal('Reemplazar el progreso de '+profile.name,'Elegirás una copia en el diálogo del sistema. Si es válida, reemplazará clases, notas, preferencias y laboratorios de este perfil.','apply-import','Elegir copia y reemplazar');break;case 'apply-import':await profileOperation(async()=>{const result=await desktop.importBackup(profile.id);if(!result.canceled&&result.profile){adopt(result.profile);toast('Copia importada en este perfil.');}closeModal();render(true);});break;case 'check-update':renderUpdate({status:'checking',message:'Buscando actualizaciones…'});try{renderUpdate(await desktop.checkForUpdates());}catch(error){renderUpdate({status:'error',message:'No se pudo buscar actualizaciones. El campus sigue disponible sin conexión.'});}break;case 'install-update':await profileOperation(()=>desktop.installUpdate());break;case 'card-flip':revealed=!revealed;drawCard();break;case 'card-next':cardIndex=(cardIndex+1)%deck.length;revealed=false;drawCard();break;case 'card-prev':cardIndex=(cardIndex+deck.length-1)%deck.length;revealed=false;drawCard();break;case 'card-lesson':openLesson(deck[cardIndex].lessonId);break;case 'continue':{const l=core.nextLesson(state,curriculum);l?openLesson(l.id):navigate('final');}break;case 'next':{const l=core.nextLesson(state,curriculum);if(l?.id===currentId)toast('Todavía falta un paso de esta clase. Podés explorar otras desde Cursos.');else l?openLesson(l.id):navigate('final');}break;case 'print':window.print();break;case 'summary-download':case 'final-download':await flush();await desktop.exportBackup(profile.id);toast('La copia incluye todos tus resúmenes y borradores del final.');break;case 'system-info':systemInfo=await desktop.getSystemLabInfo();render();break;case 'run-command':runTerminal();break;case 'hash-sample':{const digest=await window.LabEngine.hashText(activeLab.sample||'');document.getElementById('hash-output').textContent=digest;const field=document.getElementById('lab-digest');field.value=digest;field.dispatchEvent(new Event('input',{bubbles:true}));}break;}}
function runTerminal(){const input=document.getElementById('lab-command');const entry=labData[activeLab.id]||{};const result=window.LabEngine.runCommand(entry.state||window.LabEngine.startLab(activeLab.id),input.value);labData={...labData,[activeLab.id]:{...entry,state:result.state}};labOutput+=(labOutput?'\n':'')+'$ '+input.value+'\n'+result.output;persist();document.getElementById('terminal-output').textContent=labOutput;input.value='';input.focus();}
for(const type of ['click','beforeinput','input','change','submit','keydown'])document.addEventListener(type,e=>{if(profileBusy||closePending){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const run=async()=>{if(el.id==='menu-toggle'){const on=document.documentElement.classList.toggle('menu-open');el.setAttribute('aria-expanded',String(on));return;}if(el.dataset.searchIndex!==undefined){selectSearchResult(Number(el.dataset.searchIndex));return;}if(el.dataset.view){navigate(el.dataset.view);document.documentElement.classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');return;}if(el.dataset.lesson){openLesson(el.dataset.lesson,!!el.dataset.openNotes);return;}if(el.dataset.step){step=el.dataset.step;render('step-'+step);return;}if(el.dataset.material){await desktop.openMaterial(el.dataset.material);return;}if(el.dataset.exportMaterial){await desktop.exportMaterial(el.dataset.exportMaterial);return;}if(el.dataset.selectProfile){await profileOperation(async()=>{adopt(await desktop.selectProfile(el.dataset.selectProfile));view='home';render(true);});return;}if(el.dataset.lab){activeLab=window.LabEngine.catalog.find(l=>l.id===el.dataset.lab);labResult=null;labOutput='';view='lab';render(true);return;}if(el.id==='mark-read'){edit(core.updateLesson(state,currentId,{read:!prog(currentId).read}));render('mark-read');return;}if(el.id==='practice-done'){const p=prog(currentId);if(!p.practiceDone&&p.answer.trim().length<20){document.getElementById('practice-error').textContent='Primero registrá qué hiciste y observaste: al menos 20 caracteres.';document.getElementById('practice-answer').setAttribute('aria-invalid','true');document.getElementById('practice-answer').focus();return;}edit(core.updateLesson(state,currentId,{practiceDone:!p.practiceDone}));render('practice-done');return;}if(el.dataset.action)await executeAction(el.dataset.action);};run().catch(error=>{toast(error.message);updateChrome();});});
document.addEventListener('input',e=>{const el=e.target;try{if(el.id==='campus-global-query'){runGlobalSearch(el.value);return;}if(el.dataset.edit){edit(core.updateLesson(state,currentId,{[el.dataset.edit]:el.value}));}else if(el.dataset.roadmapNote){edit(core.updateRoadmapNote(state,el.dataset.roadmapNote,el.value));}else if(el.dataset.finalStation){edit({...state,updatedAt:new Date().toISOString(),final:{...state.final,stations:{...state.final.stations,[el.dataset.finalStation]:el.value}}});}else if(el.dataset.finalNotes){edit({...state,updatedAt:new Date().toISOString(),final:{...state.final,notes:el.value}});}else if(el.dataset.labNotes){const id=el.dataset.labNotes;labData={...labData,[id]:{...labData[id],notes:el.value}};persist();}else if(el.closest('#lab-form')&&el.name){const id=activeLab.id;labData={...labData,[id]:{...labData[id],answers:{...labData[id]?.answers,[el.name]:el.value}}};persist();}else if(el.id==='log-source-filter'||el.id==='log-user-filter'){document.getElementById('log-results').innerHTML=logTable();}else if(el.id==='lesson-search'){search=el.value;const temp=document.createElement('div');temp.innerHTML=route();document.getElementById('route-results').replaceWith(temp.querySelector('#route-results'));document.getElementById('route-status').textContent=temp.querySelector('#route-status').textContent;}}catch(error){toast(error.message);}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.closest('#lab-form')&&el.name){const id=activeLab.id;labData={...labData,[id]:{...labData[id],answers:{...labData[id]?.answers,[el.name]:el.value}}};persist();}if(el.dataset.preference)changePreferences({[el.dataset.preference]:el.type==='checkbox'?el.checked:el.value});if(el.dataset.roadmapTask){edit(core.updateRoadmapTask(state,el.dataset.roadmapTask,el.checked));document.getElementById('roadmap-progress').innerHTML=roadmapMeter();}if(el.id==='deck-filter'){makeDeck(el.value);drawCard();}if(el.type==='radio'&&el.closest('#quiz-form'))document.getElementById('quiz-result').textContent='Elección actualizada. Corregí para ver el resultado de este intento.';}catch(error){toast(error.message);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;const run=async()=>{if(form.id==='create-profile-form'){const name=document.getElementById('profile-name').value.trim();if(!name){document.getElementById('profile-name').focus();toast('Escribí un nombre para tu perfil.');return;}await profileOperation(async()=>{adopt(await desktop.createProfile(name));profiles=await desktop.listProfiles();view='home';render(true);});return;}if(form.id==='rename-profile-form'){const name=document.getElementById('rename-profile').value.trim();await profileOperation(async()=>{const renamed=await desktop.renameProfile({id:profile.id,name});profile={...profile,name:renamed.name,revision:renamed.revision};profiles=await desktop.listProfiles();render(true);});return;}if(form.id==='quiz-form'){const l=lessonById(currentId),answers={};l.quiz.forEach(q=>{const checked=[...form.elements].find(el=>el.name==='q-'+q.id&&el.checked);if(checked)answers[q.id]=Number(checked.value);});try{edit(core.recordQuiz(state,l,answers));render('quiz-result');announce('Resultado: '+prog(l.id).lastScore+' de 3.');}catch(error){document.getElementById('quiz-result').textContent=error.message;const missing=l.quiz.find(q=>!Object.hasOwn(answers,q.id));if(missing){const field=form.querySelector(`[data-question="${missing.id}"]`);field.setAttribute('aria-invalid','true');field.querySelector('input').focus();}}return;}if(form.id==='lab-form'){const id=activeLab.id,attemptProfile=profile.id,attemptGeneration=profileGeneration,entry=labData[id]||{},answers={};let executionOutput='';for(const el of form.elements)if(el.name)answers[el.name]=el.value;if(id==='linux-permissions')answers.state=entry.state||window.LabEngine.startLab(id);if(id==='sql-investigation'){answers.result=await desktop.runSqlLab({query:answers.query,taskId:id});if(profileBusy||profile.id!==attemptProfile||profileGeneration!==attemptGeneration)return;executionOutput='Consulta ejecutada: '+answers.query+'\n\n'+answers.result.columns.join(' | ')+'\n'+answers.result.rows.map(row=>row.join(' | ')).join('\n')+'\n'+answers.result.rowCount+' filas · '+answers.result.elapsedMs+' ms'+(answers.result.truncated?' · Resultado truncado':'');}const result=await window.LabEngine.evaluate(id,answers);if(profileBusy||profile.id!==attemptProfile||profileGeneration!==attemptGeneration)return;const latest=labData[id]||entry;const storedAnswers=id==='sql-investigation'?{query:latest.answers?.query??answers.query}:{...answers,...latest.answers};const execution=id==='sql-investigation'?{lastExecutedQuery:answers.query,lastExecution:{rowCount:answers.result.rowCount,truncated:answers.result.truncated,elapsedMs:answers.result.elapsedMs}}:{};labData={...labData,[id]:{...latest,answers:storedAnswers,...execution,attempts:(latest.attempts||0)+1,evidence:result.evidence,lastResult:{score:result.score,total:result.total,passed:result.passed},updatedAt:new Date().toISOString()}};persist();if(view==='lab'&&activeLab?.id===id){if(id==='sql-investigation')labOutput=executionOutput;labResult=result;render('lab-feedback');}}};run().catch(error=>toast(error.message));});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();globalSearch();return;}const dialog=document.querySelector('[role="dialog"]');if(dialog){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const focusable=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}else if(e.key==='Enter'&&e.target.id==='lab-command'){e.preventDefault();try{runTerminal();}catch(error){toast(error.message);}}});
window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(effectivePreferences().theme==='system')applyPreferences();});
async function init(){if(!desktop){main.innerHTML=title('APLICACIÓN DE ESCRITORIO','Abrí Campus desde su acceso directo.','La interfaz de guardado local está disponible dentro de la aplicación instalada.');return;}desktop.onBeforeClose(beforeClose);desktop.onUpdateStatus(renderUpdate);try{const result=await Promise.all([desktop.getAppInfo(),desktop.getActiveProfile(),desktop.listProfiles()]);info=result[0];profiles=result[2];if(result[1])adopt(result[1]);render();}catch(error){if(window.RecoveryHub){view='recovery';render(true)}else main.innerHTML=title('NO PUDIMOS ABRIR LOS DATOS','Tu archivo original se conserva.',error.message)+`<p>Reiniciá la aplicación o revisá la carpeta de datos. No se reemplazó el perfil por uno vacío.</p>`;}}
init();
})();
